<script>
 import SemanticMetadataSearch from '../../src/components/defiant/SemanticMetadataSearch.svelte';
 let scope=$state('fixture_org'),configured=$state(true),period=$state('undated'),session=$state(new URL(location.href).searchParams.get('session')||''),offset=$state(Number(new URL(location.href).searchParams.get('offset')||0)),count=$state(Number(sessionStorage.getItem('semantic-posts')||0)),selected=$state(''),hold=$state(false),waiting=$state(false),timeoutOnce=false,keys=$state([]);
 let release;
 const revision='a'.repeat(64),key='semantic-invented-record';
 async function request(path,options={}){const body=options.body?JSON.parse(options.body):null,scopeAtCall=scope;let record=JSON.parse(sessionStorage.getItem(key)||'null');if(body){count++;sessionStorage.setItem('semantic-posts',String(count));keys=[...keys,body.idempotencyKey];if(hold){waiting=true;await new Promise(resolve=>release=resolve);waiting=false;}record={sessionId:'b'.repeat(64),filters:{periodPresence:body.periodPresence},expiresAt:'2099-01-01T00:00:00.000Z'};sessionStorage.setItem(key,JSON.stringify(record));if(timeoutOnce){timeoutOnce=false;throw Object.assign(Error('Uncertain'),{status:408});}}if(!record)throw Object.assign(Error('Session expired'),{status:409});const start=body?0:Number(new URL(path,'https://fixture.invalid').searchParams.get('offset')||0);return {scope:{organizationId:scopeAtCall},revision,mode:'semantic',...record,offset:start,limit:25,total:26,nextOffset:start===0?25:null,items:Array.from({length:start===0?25:1},(_,i)=>({id:'row_'+(start+i),kind:'root',filename:`${start+i} <img onerror=x> invented.csv`,sha256:'c'.repeat(64),format:'csv',similarity:0.5}))};}
 function navigate(id,start){session=id;offset=start;const url=new URL(location.href);if(id){url.searchParams.set('session',id);url.searchParams.set('offset',String(start));}else{url.searchParams.delete('session');url.searchParams.delete('offset');}history.replaceState(null,'',url);}
</script>
<p>Invented component fixture. No hosted model.</p><label>Exact period filter<select bind:value={period}><option value="undated">Undated</option><option value="dated">Dated</option></select></label><button onclick={()=>configured=false}>Disable configuration</button><button onclick={()=>{scope='other_org';navigate('',0);}}>Switch account scope</button><button onclick={()=>hold=true}>Hold response</button><button onclick={()=>release?.()}>Release response</button><button onclick={()=>timeoutOnce=true}>One uncertain response</button><output aria-label="Post count">{count}</output><output aria-label="Waiting">{String(waiting)}</output><output aria-label="Request keys">{keys.join(',')}</output><output aria-label="Selected source">{selected}</output>
{#key scope}<SemanticMetadataSearch {request} {revision} organizationId={scope} {configured} filters={{periodPresence:period}} sessionId={session} {offset} onSession={navigate} onSource={hash=>selected=hash}/>{/key}
<style>output{display:block;overflow-wrap:anywhere}:global(body){margin:0}button,select{max-width:100%}</style>
